using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Xml;using System.Collections.Generic;using System.Security.Cryptography;
namespace BeamScheduleFormatter {
sealed class PowSourceFile {
 internal readonly string Id,Name,Kind,Sha256;internal readonly bool RecoveredText;readonly byte[] data;byte[] packed;
 internal string Text(){using(var input=new MemoryStream(data))using(var reader=new StreamReader(input,Encoding.UTF8,true))return reader.ReadToEnd();}
 internal long Size{get{return data.LongLength;}}internal byte[] Bytes(){return (byte[])data.Clone();}
 internal static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 internal PowSourceFile(string name,string kind,byte[] bytes,bool recovered=false){Name=SafeName(name);Kind=(kind??"").Trim();if(Kind.Length==0||Kind.Length>100)throw new Exception("Invalid project source kind.");if(bytes==null||bytes.LongLength>PowSourceFiles.MaxFileBytes)throw new Exception("Project source files support up to 32 MiB per file.");data=(byte[])bytes.Clone();Sha256=Hash(data);RecoveredText=recovered;Id=Hash(Encoding.UTF8.GetBytes(Kind.ToUpperInvariant()+"\0"+Name.ToUpperInvariant()+"\0"+Sha256));}
 internal static string SafeName(string value){value=(value??"").Replace('\\','/');value=value.Substring(value.LastIndexOf('/')+1);if(value.Length==0||value.Length>255||value=="."||value==".."||value.EndsWith(".")||value.EndsWith(" ")||value.Any(c=>c<32||"<>:\"/\\|?*".IndexOf(c)>=0))throw new Exception("Invalid project source filename.");return value;}
 internal byte[] Packed(){if(packed==null)using(var output=new MemoryStream()){using(var zip=new GZipStream(output,CompressionMode.Compress,true))zip.Write(data,0,data.Length);packed=output.ToArray();}return packed;}
}
sealed class PowSourceFiles {
 internal const int MaxFileBytes=32*1024*1024,MaxTotalBytes=128*1024*1024,MaxFiles=256;readonly List<PowSourceFile> files=new List<PowSourceFile>();
 internal IList<PowSourceFile> Files{get{return files.AsReadOnly();}}
 internal Action<PowSourceFile> BeforeAdd;
 internal void Add(PowSourceFile file){if(BeforeAdd!=null)BeforeAdd(file);var same=files.Where(f=>f.Name.Equals(file.Name,StringComparison.OrdinalIgnoreCase)&&f.Kind.Equals(file.Kind,StringComparison.OrdinalIgnoreCase)).ToList();if(file.RecoveredText&&same.Any(f=>!f.RecoveredText))return;var remove=file.RecoveredText?new List<PowSourceFile>():same.Where(f=>f.RecoveredText).ToList();if(files.Any(f=>f.Id==file.Id&&!remove.Contains(f)))return;if(files.Count-remove.Count>=MaxFiles||files.Sum(f=>f.Size)-remove.Sum(f=>f.Size)+file.Size>MaxTotalBytes)throw new Exception("Project sources exceed 256 files or 128 MiB total. Save unneeded references separately.");foreach(var old in remove)files.Remove(old);files.Add(file);}
 internal void AddRange(IEnumerable<PowSourceFile> source){foreach(var file in source)Add(file);}
 internal static PowSourceFile ReadFile(string path,string kind){using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(input.Length>MaxFileBytes)throw new Exception("Project source files support up to 32 MiB per file: "+Path.GetFileName(path));using(var output=new MemoryStream()){var buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){if(output.Length+n>MaxFileBytes)throw new Exception("Project source grew beyond supported size.");output.Write(buffer,0,n);}return new PowSourceFile(Path.GetFileName(path),kind,output.ToArray());}}}
 internal void CaptureFile(string path,string kind){Add(ReadFile(path,kind));}
 internal void CaptureText(string name,string kind,string text){if(files.Any(f=>f.Kind==kind&&f.Name.Equals(PowSourceFile.SafeName(name),StringComparison.OrdinalIgnoreCase)))return;Add(new PowSourceFile(name,kind,new UTF8Encoding(false).GetBytes(text??""),true));}
 internal void Replace(PowSourceFiles source){files.Clear();files.AddRange(source.files);}
 internal void Write(XmlElement root,bool manifestOnly=false){var section=root.OwnerDocument.CreateElement(manifestOnly?"SourceFileManifest":"SourceFiles");section.SetAttribute("version","1");root.AppendChild(section);foreach(var file in files.OrderBy(f=>f.Id,StringComparer.Ordinal)){var e=root.OwnerDocument.CreateElement("File");e.SetAttribute("id",file.Id);e.SetAttribute("name",file.Name);e.SetAttribute("kind",file.Kind);e.SetAttribute("sha256",file.Sha256);e.SetAttribute("size",file.Size.ToString(System.Globalization.CultureInfo.InvariantCulture));e.SetAttribute("recoveredText",file.RecoveredText.ToString());if(!manifestOnly){e.SetAttribute("encoding","gzip-base64");e.InnerText=Convert.ToBase64String(file.Packed());}section.AppendChild(e);}}
 internal static PowSourceFiles Read(XmlElement root){var result=new PowSourceFiles();var sections=root.SelectNodes("SourceFiles");if(sections.Count==0){if(root.SelectNodes("SourceFileManifest/File").Count>0)throw new Exception("Saved project is missing its embedded source files.");return result;}if(sections.Count!=1)throw new Exception("Duplicate project source archive.");var section=(XmlElement)sections[0];if(section.GetAttribute("version")!="1"||section.ChildNodes.Count>MaxFiles)throw new Exception("Unsupported project source archive.");var ids=new HashSet<string>(StringComparer.Ordinal);long total=0;foreach(XmlElement e in section.SelectNodes("File")){long size;bool recovered;if(!long.TryParse(e.GetAttribute("size"),out size)||size<0||size>MaxFileBytes||(total+=size)>MaxTotalBytes||e.GetAttribute("encoding")!="gzip-base64"||!bool.TryParse(e.GetAttribute("recoveredText"),out recovered)||e.InnerText.Length>MaxFileBytes*2)throw new Exception("Invalid or oversized project source file.");string name=e.GetAttribute("name");if(PowSourceFile.SafeName(name)!=name)throw new Exception("Project source filename must not contain a path.");byte[] payload=Convert.FromBase64String(e.InnerText),bytes;using(var input=new MemoryStream(payload))using(var zip=new GZipStream(input,CompressionMode.Decompress))using(var output=new MemoryStream()){var buffer=new byte[65536];int n;while((n=zip.Read(buffer,0,buffer.Length))>0){if(output.Length+n>size)throw new Exception("Project source expands beyond its recorded size.");output.Write(buffer,0,n);}bytes=output.ToArray();}var file=new PowSourceFile(name,e.GetAttribute("kind"),bytes,recovered);if(file.Size!=size||file.Sha256!=e.GetAttribute("sha256")||file.Id!=e.GetAttribute("id")||!ids.Add(file.Id))throw new Exception("Project source integrity check failed: "+name);result.Add(file);}if(result.Files.Count!=section.SelectNodes("File").Count)throw new Exception("Duplicate or conflicting project source records.");var manifest=root.SelectNodes("SourceFileManifest");if(manifest.Count>1)throw new Exception("Duplicate project source manifest.");if(manifest.Count==1){var expected=((XmlElement)manifest[0]).SelectNodes("File").Cast<XmlElement>().Select(e=>e.GetAttribute("id")).OrderBy(x=>x,StringComparer.Ordinal).ToArray();var actual=result.Files.Select(f=>f.Id).OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(!expected.SequenceEqual(actual))throw new Exception("Embedded project sources do not match the saved manifest.");}return result;}
}
}
